import java.util.Scanner

const val MOD = 1_000_000_007L

fun power(base: Long, exp: Long, mod: Long): Long {
    var b = base % mod
    var e = exp
    var result = 1L
    while (e > 0) {
        if (e and 1L == 1L) {
            result = result * b % mod
        }
        b = b * b % mod
        e = e shr 1
    }
    return result
}

fun main() {
    val scanner = Scanner(System.`in`)
    val n = scanner.nextInt()
    val x = scanner.nextInt()
    val pos = scanner.nextInt()

    val maxN = n + 1
    val fact = LongArray(maxN + 1)
    fact[0] = 1L
    for (i in 1..maxN) {
        fact[i] = fact[i - 1] * i % MOD
    }

    fun inverseFact(k: Int): Long {
        return power(fact[k], MOD - 2, MOD)
    }

    fun comb(a: Int, b: Int): Long {
        if (b < 0 || b > a) return 0L
        return fact[a] * inverseFact(b) % MOD * inverseFact(a - b) % MOD
    }

    var lo = 0
    var hi = n - 1
    var needLess = 0
    var needGreater = 0
    var possible = true

    while (lo < hi) {
        val mid = (lo + hi) / 2
        if (mid < pos) {
            needLess++
            lo = mid + 1
        } else if (mid > pos) {
            needGreater++
            hi = mid
        } else {
            // mid == pos, a[mid] == x, condition a[mid] < x is false, so high = mid
            hi = mid
        }
    }

    if (lo != pos) {
        possible = false
    }

    if (needLess > x - 1 || needGreater > n - x) {
        possible = false
    }

    if (!possible) {
        println(0)
        return
    }

    val remaining = n - 1 - needLess - needGreater

    val ans = comb(x - 1, needLess) * fact[needLess] % MOD *
            comb(n - x, needGreater) % MOD * fact[needGreater] % MOD *
            fact[remaining] % MOD

    println(ans)
}
